package com.aoo.bcg.common.concurrency;import org.junit.jupiter.api.Test;import java.time.*;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
class FairEntitySchedulerTest{@Test void hotEntityCannotStarvePeerAndLateWorkIsReported(){var q=new FairEntityScheduler<String,Integer>(4,8,Duration.ofMillis(10));var at=Instant.EPOCH;q.offer("hot",1,at);q.offer("hot",2,at);q.offer("peer",3,at);q.offer("hot",4,at);var late=new ArrayList<FairEntityScheduler.Entry<String,Integer>>();assertEquals(List.of("hot","peer","hot","hot"),java.util.stream.IntStream.range(0,4).mapToObj(i->q.poll(at.plusMillis(20),late::add).orElseThrow().key()).toList());assertEquals(4,late.size());}}
